#!/usr/bin/env node
/**
 * Builds two static evidence pages from the lighthouse JSON reports under
 * public/lighthouse-reports/:
 *
 *   public/lighthouse-reports/index.html         — directory of all reports
 *   public/lighthouse-reports/bundle-sizes.html  — per-page transfer breakdown
 *
 * These pages serve as the linked evidence behind every claim/number on the
 * marketing pages. Each report is generated by Lighthouse 12.x with the same
 * preset PageSpeed Insights uses (mobile = Slow 4G + 4× CPU; desktop = wide
 * viewport, no throttling).
 */

import { readFileSync, writeFileSync, readdirSync } from 'node:fs';
import { join } from 'node:path';

const ROOT = new URL('..', import.meta.url).pathname;
const REPORTS_DIR = join(ROOT, 'public/lighthouse-reports');

const FEATURES = [
  { slug: 'blog',           label: 'Blog Post',         path: '/blog'           },
  { slug: 'product',        label: 'Product Page',      path: '/product'        },
  { slug: 'restaurant_1',   label: 'Restaurant Detail', path: '/restaurant/1'   },
  { slug: 'product-search', label: 'Product Search',    path: '/product-search' },
];
const VARIANTS  = ['ssr', 'client', 'rsc'];
const STRATEGIES = ['desktop', 'mobile'];

function loadReport(featureSlug, variant, strategy) {
  // File names use slug like `blog`, `restaurant_1`, etc.
  const safe = `${featureSlug}_${variant}-${strategy}`;
  const path = join(REPORTS_DIR, `${safe}.json`);
  try {
    return { safe, json: JSON.parse(readFileSync(path, 'utf8')) };
  } catch {
    return null;
  }
}

function metrics(j) {
  const a = j.audits;
  const score = Math.round(j.categories.performance.score * 100);
  return {
    score,
    fcp:      a['first-contentful-paint'].numericValue,
    lcp:      a['largest-contentful-paint'].numericValue,
    tbt:      a['total-blocking-time'].numericValue,
    cls:      a['cumulative-layout-shift'].numericValue,
    si:       a['speed-index'].numericValue,
    bootup:   a['bootup-time'].numericValue,
    transfer: a['total-byte-weight'].numericValue,
    requests: a['network-requests']?.details?.items || [],
  };
}

const ms = (v) => v == null ? '—' : (v < 1000 ? `${Math.round(v)} ms` : `${(v/1000).toFixed(2)} s`);
const kb = (v) => v == null ? '—' : (v >= 1024*1024 ? `${(v/1024/1024).toFixed(2)} MB` : `${Math.round(v/1024)} KB`);
const cls = (v) => v == null ? '—' : v.toFixed(3);
const sign = (n) => n > 0 ? '+' : '';

function htmlEscape(s) {
  return String(s).replace(/[&<>"']/g, (c) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

function appUrl(feature, variant, strategy = 'desktop') {
  return `${feature.path}/${variant}${strategy === 'desktop' ? '?delay=50' : ''}`;
}

function variantLabel(variant) {
  return variant === 'client' ? 'Client' : variant.toUpperCase();
}

// ───────── PAGE 1: index.html ─────────
function buildIndex() {
  const rows = [];
  for (const f of FEATURES) {
    for (const v of VARIANTS) {
      for (const s of STRATEGIES) {
        const r = loadReport(f.slug, v, s);
        if (!r) continue;
        const m = metrics(r.json);
        rows.push({ feature: f, variant: v, strategy: s, m, safe: r.safe });
      }
    }
  }

  const featureBlocks = FEATURES.map((f) => {
    const tableRows = ['ssr','client','rsc'].flatMap((v) =>
      ['desktop','mobile'].map((s) => {
        const row = rows.find((x) => x.feature.slug === f.slug && x.variant === v && x.strategy === s);
        if (!row) return '';
        const m = row.m;
        const reportLink = `${row.safe}.html`;
        // Side-by-side compare URL: pair this report with the opposite-end variant.
        const compareUrl = v === 'rsc'
          ? `/lh-compare?left=${f.slug}_ssr-${s}&right=${row.safe}`
          : `/lh-compare?left=${row.safe}&right=${f.slug}_rsc-${s}`;
        const measuredAppUrl = appUrl(f, v, s);
        return `<tr>
          <td class="variant ${v}">${v.toUpperCase()}</td>
          <td>${s}</td>
          <td><a class="app-inline ${v}" href="${htmlEscape(measuredAppUrl)}">${variantLabel(v)} app ↗</a></td>
          <td class="num"><span class="score score-${scoreColor(m.score)}"><a href="${compareUrl}" style="color:inherit;text-decoration:none">${m.score}</a></span></td>
          <td class="num">${ms(m.fcp)}</td>
          <td class="num">${ms(m.lcp)}</td>
          <td class="num">${ms(m.tbt)}</td>
          <td class="num">${ms(m.bootup)}</td>
          <td class="num">${kb(m.transfer)}</td>
          <td><a href="${compareUrl}">${v === 'rsc' ? 'SSR vs RSC' : v.toUpperCase() + ' vs RSC'} ↗</a> · <a href="${reportLink}" class="muted">solo</a></td>
        </tr>`;
      })
    ).join('');
    return `<section class="feature">
      <h2>${f.label} <span class="path">(${f.path})</span></h2>
      <table>
        <thead>
          <tr><th>Variant</th><th>Strategy</th><th>App</th><th>Perf</th><th>FCP</th><th>LCP</th><th>TBT</th><th>Bootup</th><th>Transfer</th><th>Report</th></tr>
        </thead>
        <tbody>${tableRows}</tbody>
      </table>
    </section>`;
  }).join('');

  const html = `<!doctype html>
<html lang="en"><head>
<meta charset="utf-8">
<title>Lighthouse evidence — LocalHub demo</title>
<meta name="viewport" content="width=device-width,initial-scale=1">
<style>${commonCss()}</style>
</head><body>
<header class="page-head">
  <a href="/" class="back">← Back to demo</a>
  <h1>Lighthouse evidence</h1>
  <p class="lede">Every number cited on the home page and on /rsc-performance is derived from one of these Lighthouse reports. Lighthouse 12 with PageSpeed Insights' standard presets — mobile = Slow 4G + 4× CPU throttling; desktop = unthrottled, 1350×940 viewport. Open any row's report to see the raw audit, network waterfall, and diagnostics, or use its app link to inspect the measured variant.</p>
  <p class="lede small">See also: <a href="bundle-sizes.html">bundle-size breakdown</a> — what each variant ships to the browser, and why the RSC variants ship less.</p>
</header>
${featureBlocks}
<footer><p>Reports generated against the local docker image (<code>lhd:lean</code>) on port 3040. Same artefact as the production deployment — re-run any URL through <a href="https://pagespeed.web.dev/">pagespeed.web.dev</a> after deploy for field-condition equivalent.</p></footer>
</body></html>`;
  writeFileSync(join(REPORTS_DIR, 'index.html'), html);
  return rows;
}

function scoreColor(n) { return n >= 90 ? 'good' : n >= 50 ? 'mid' : 'bad'; }

// ───────── PAGE 2: bundle-sizes.html ─────────
function buildBundles(rows) {
  // Group network requests by page (use desktop reports for the canonical numbers).
  const pages = [];
  for (const f of FEATURES) {
    for (const v of VARIANTS) {
      const row = rows.find((x) => x.feature.slug === f.slug && x.variant === v && x.strategy === 'desktop');
      if (!row) continue;
      const reqs = row.m.requests || [];
      const hostReqs = reqs.filter((r) => /rsc\.reactonrails\.com/.test(r.url));
      const byType = {};
      for (const r of hostReqs) {
        const t = r.resourceType || 'Other';
        if (!byType[t]) byType[t] = { count: 0, transferSize: 0, resourceSize: 0, items: [] };
        byType[t].count += 1;
        byType[t].transferSize += r.transferSize || 0;
        byType[t].resourceSize += r.resourceSize || 0;
        byType[t].items.push({ url: r.url, transferSize: r.transferSize || 0, resourceSize: r.resourceSize || 0 });
      }
      // Find the heavy script chunks of interest
      const scripts = (byType['Script']?.items || []).slice().sort((a,b) => b.transferSize - a.transferSize);
      const heavyScripts = scripts.filter((s) => /markdown-libs|charting-libs|7161|6308|6091|client-bundle|generated\//.test(s.url));
      const compareUrl = v === 'rsc'
        ? `/lh-compare?left=${f.slug}_ssr-desktop&right=${row.safe}`
        : `/lh-compare?left=${row.safe}&right=${f.slug}_rsc-desktop`;
      pages.push({ feature: f, variant: v, totalTransfer: row.m.transfer, byType, scripts, heavyScripts, reportLink: `${row.safe}.html`, compareUrl });
    }
  }

  function pageBlock(p) {
    const route = appUrl(p.feature, p.variant, 'desktop');
    const itemRows = (Object.entries(p.byType)).map(([t, info]) =>
      `<tr><td>${t}</td><td class="num">${info.count}</td><td class="num">${kb(info.transferSize)}</td></tr>`
    ).join('');

    const scriptRows = p.scripts.slice(0, 12).map((s) => {
      const path = s.url.replace(/^https?:\/\/[^/]+/, '');
      const tag = annotateScript(path);
      return `<tr><td><code>${htmlEscape(path)}</code> ${tag}</td><td class="num">${kb(s.transferSize)}</td></tr>`;
    }).join('');

    return `<section class="bundle">
      <h3 class="bundle-title">
        <span class="variant ${p.variant}">${p.variant.toUpperCase()}</span>
        <a class="route" href="${htmlEscape(route)}">${htmlEscape(route)}</a>
        <span class="meta">total transfer ${kb(p.totalTransfer)}</span>
        <a class="report-link" href="${p.compareUrl}">${p.variant === 'rsc' ? 'SSR vs RSC' : p.variant.toUpperCase() + ' vs RSC'} side-by-side →</a>
      </h3>
      <div class="bundle-grid">
        <div>
          <h4>By resource type</h4>
          <table class="compact"><thead><tr><th>Type</th><th>Count</th><th>Transferred</th></tr></thead><tbody>${itemRows}</tbody></table>
        </div>
        <div>
          <h4>Top scripts (transferred bytes)</h4>
          <table class="compact"><thead><tr><th>Script</th><th>Size</th></tr></thead><tbody>${scriptRows}</tbody></table>
        </div>
      </div>
    </section>`;
  }

  // Use a friendly anchor (the route's last segment, e.g. /blog → "blog",
  // /product-search → "product-search", /restaurant/1 → "restaurant").
  function anchorFor(f) {
    if (f.path === '/restaurant/1') return 'restaurant';
    return f.path.replace(/^\//, '');
  }

  const featureBlocks = FEATURES.map((f) => {
    const ssr  = pages.find((p) => p.feature.slug === f.slug && p.variant === 'ssr');
    const cli  = pages.find((p) => p.feature.slug === f.slug && p.variant === 'client');
    const rsc  = pages.find((p) => p.feature.slug === f.slug && p.variant === 'rsc');
    if (!ssr || !cli || !rsc) return '';
    const delta = rsc.totalTransfer - ssr.totalTransfer;
    return `<article class="feature-bundle" id="${anchorFor(f)}">
      <header class="feature-header">
        <h2>${f.label} <code class="path">${f.path}</code></h2>
        <p class="diff">RSC ships <strong>${sign(delta)}${kb(Math.abs(delta))}</strong> ${delta < 0 ? 'less' : 'more'} than SSR &mdash; click a chunk URL in any table below to inspect it directly.</p>
      </header>
      ${pageBlock(ssr)}
      ${pageBlock(cli)}
      ${pageBlock(rsc)}
    </article>`;
  }).join('');

  const html = `<!doctype html>
<html lang="en"><head>
<meta charset="utf-8">
<title>Bundle-size evidence — LocalHub demo</title>
<meta name="viewport" content="width=device-width,initial-scale=1">
<style>${commonCss()}</style>
</head><body>
<header class="page-head">
  <a href="/" class="back">← Back to demo</a>
  <h1>Bundle-size evidence</h1>
  <p class="lede">Every "X MB less to the client" claim on the marketing pages is rooted in this table. The numbers come from the Lighthouse network-request audit: real bytes transferred over the wire (compressed where applicable). Each route label opens the measured desktop app variant, and each script row links to the file Lighthouse measured.</p>
  <p class="lede small">See also: <a href="index.html">all Lighthouse reports</a>.</p>
</header>
${featureBlocks}
</body></html>`;
  writeFileSync(join(REPORTS_DIR, 'bundle-sizes.html'), html);
}

function annotateScript(path) {
  if (/markdown-libs/.test(path))  return '<span class="tag tag-warn">marked + highlight.js</span>';
  if (/charting-libs/.test(path))  return '<span class="tag tag-warn">d3-* split chunk</span>';
  if (/7161/.test(path))           return '<span class="tag tag-warn">react-on-rails-pro core</span>';
  if (/6091/.test(path))           return '<span class="tag tag-info">RSC vendor</span>';
  if (/6308/.test(path))           return '<span class="tag tag-info">vendor</span>';
  if (/runtime/.test(path))        return '<span class="tag">webpack runtime</span>';
  if (/client-bundle/.test(path))  return '<span class="tag">app entry</span>';
  if (/generated\/.+RSC/.test(path)) return '<span class="tag tag-good">RSC entry pack</span>';
  if (/generated\/.+SSR/.test(path)) return '<span class="tag tag-warn">SSR entry pack</span>';
  if (/generated\/.+Client/.test(path)) return '<span class="tag tag-warn">client entry pack</span>';
  return '';
}

function commonCss() {
  return `
    *{box-sizing:border-box}
    html{scroll-behavior:smooth}
    body{font-family:system-ui,-apple-system,Segoe\\ UI,Roboto,sans-serif;margin:0;background:#f8fafc;color:#0f172a;line-height:1.5}
    .feature-bundle{scroll-margin-top:1.5rem;transition:box-shadow .3s,border-color .3s}
    .feature-bundle:target{border-color:#6366f1;box-shadow:0 0 0 3px rgba(99,102,241,.25),0 4px 18px rgba(15,23,42,.08)}
    .page-head{padding:2rem 1.5rem;background:white;border-bottom:1px solid #e2e8f0}
    .page-head .back{font-size:.85rem;color:#475569;text-decoration:none}
    .page-head .back:hover{color:#1e293b;text-decoration:underline}
    .page-head h1{margin:.5rem 0 .75rem;font-size:1.75rem}
    .lede{max-width:60rem;color:#475569;font-size:.95rem;margin:0 0 .5rem}
    .lede.small{font-size:.85rem}
    .feature, .feature-bundle{padding:1.5rem;max-width:88rem;margin:1.5rem auto;background:white;border:1px solid #e2e8f0;border-radius:.75rem;box-shadow:0 1px 2px rgba(15,23,42,.04)}
    .feature h2, .feature-bundle h2{margin:0 0 .75rem;font-size:1.2rem}
    .feature h2 .path, .feature-bundle code.path{font-family:ui-monospace,monospace;color:#94a3b8;font-weight:400;font-size:.85rem;background:#f1f5f9;padding:.1rem .4rem;border-radius:.25rem}
    .app-inline{font-size:.78rem;font-weight:600}
    .app-inline.ssr{color:#1d4ed8}
    .app-inline.client{color:#92400e}
    .app-inline.rsc{color:#047857}
    table{width:100%;border-collapse:collapse;font-size:.9rem;margin:0}
    table.compact{font-size:.82rem}
    th,td{padding:.4rem .6rem;text-align:left;border-bottom:1px solid #f1f5f9;vertical-align:top}
    th{background:#f8fafc;font-weight:600;font-size:.8rem;text-transform:uppercase;letter-spacing:.05em;color:#64748b}
    .num{font-variant-numeric:tabular-nums;font-family:ui-monospace,monospace;text-align:right}
    .variant{font-size:.7rem;text-transform:uppercase;font-weight:700;letter-spacing:.06em;padding:.15rem .5rem;border-radius:.25rem;display:inline-block}
    .variant.ssr   {background:#dbeafe;color:#1e40af}
    .variant.client{background:#fef3c7;color:#92400e}
    .variant.rsc   {background:#dcfce7;color:#14532d}
    .score{display:inline-block;min-width:2.5rem;padding:.15rem .4rem;border-radius:.25rem;font-weight:700;text-align:center}
    .score-good{background:#dcfce7;color:#14532d}
    .score-mid{background:#fef3c7;color:#92400e}
    .score-bad{background:#fee2e2;color:#991b1b}
    a{color:#4f46e5;text-decoration:none}
    a:hover{text-decoration:underline}
    a.muted{color:#94a3b8;font-size:.78rem}
    .feature-header{margin-bottom:1rem}
    .feature-header .diff{margin:.5rem 0 0;color:#475569}
    .bundle{margin-top:1rem;padding-top:1rem;border-top:1px dashed #e2e8f0}
    .bundle-title{display:flex;align-items:center;gap:.7rem;flex-wrap:wrap;font-size:1rem;margin:0 0 .75rem}
    .bundle-title .meta{color:#64748b;font-size:.85rem;font-weight:500}
    .bundle-title .route{font-family:ui-monospace,monospace;color:#1e293b}
    .bundle-title .report-link{margin-left:auto;font-size:.85rem}
    .bundle-grid{display:grid;grid-template-columns:1fr 1.5fr;gap:1.5rem}
    @media (max-width:900px){.bundle-grid{grid-template-columns:1fr}}
    code{font-family:ui-monospace,monospace;font-size:.82rem;color:#1e293b}
    .tag{display:inline-block;font-size:.7rem;padding:.1rem .4rem;border-radius:.25rem;background:#f1f5f9;color:#475569;margin-left:.4rem}
    .tag-good{background:#dcfce7;color:#14532d}
    .tag-warn{background:#fef3c7;color:#92400e}
    .tag-info{background:#e0e7ff;color:#3730a3}
    footer{padding:1.5rem;color:#64748b;font-size:.85rem;text-align:center}
  `;
}

const rows = buildIndex();
buildBundles(rows);
console.log('Wrote:');
console.log('  ' + join(REPORTS_DIR, 'index.html'));
console.log('  ' + join(REPORTS_DIR, 'bundle-sizes.html'));
